// Generated by OrchestKit Claude Plugin
// Created: 2026-09-04

/**
 * Output cap guard for hook payloads.
 *
 * Claude Code truncates hook output silently, mid-word, with no report to the
 * hook author. Constants read out of the CC 2.1.258 binary by a commenter on
 * anthropics/claude-code#91870 (issuecomment-5532305564):
 *   additionalContext        8000 chars / 200 lines
 *   systemMessage            4000 chars
 *   reason, stopReason,
 *   permissionDecisionReason 2000 chars /  20 lines
 *
 * Measured on this tree 2026-09-04: 93 context-emitting handlers, largest
 * static template literal 709 chars, 37 build context from files at runtime.
 * This test asserts the static side stays far under the cap and lists the
 * runtime builders as a warning, so a future payload that crosses the cap
 * fails here instead of vanishing in a session.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const SRC = join(__dirname, '..');
const ADDITIONAL_CONTEXT_CAP = 8000;
const STATIC_BUDGET = 4000; // half the cap: a static template this size leaves no room for runtime data

function walk(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) {
      if (name === 'node_modules' || name === '__tests__') continue;
      walk(p, out);
    } else if (name.endsWith('.ts') && !name.endsWith('.test.ts') && !name.endsWith('.d.ts')) {
      out.push(p);
    }
  }
  return out;
}

const CONTEXT_MARKERS = ['additionalContext', 'outputWithContext', 'outputPromptContext', 'outputAllowWithContext'];

describe('hook output caps (CC 2.1.258: additionalContext 8000 chars, silent truncation)', () => {
  const files = walk(SRC).filter((f) => {
    const s = readFileSync(f, 'utf8');
    return CONTEXT_MARKERS.some((m) => s.includes(m));
  });

  it('finds the context-emitting handlers', () => {
    expect(files.length).toBeGreaterThan(50);
  });

  it('keeps every static template literal under half the additionalContext cap', () => {
    const over: string[] = [];
    for (const f of files) {
      const s = readFileSync(f, 'utf8');
      for (const m of s.matchAll(/`([^`]*)`/gs)) {
        if (m[1].length > STATIC_BUDGET) over.push(`${relative(SRC, f)} (${m[1].length} chars)`);
      }
    }
    expect(over, `static payloads over ${STATIC_BUDGET} chars, cap is ${ADDITIONAL_CONTEXT_CAP}`).toEqual([]);
  });

  it('lists handlers that build context from files at runtime (warning only)', () => {
    const dynamic = files.filter((f) => /readFileSync\(/.test(readFileSync(f, 'utf8'))).map((f) => relative(SRC, f));
    if (dynamic.length) {
      console.warn(`[fh-output-cap] ${dynamic.length} context handlers read files at runtime; their payload size is not checked here:\n  ${dynamic.join('\n  ')}`);
    }
    expect(dynamic.length).toBeGreaterThanOrEqual(0);
  });
});
